#!/usr/bin/env python3
"""Apply Android release hardening to a Flutter project generated by flutter create."""
from pathlib import Path
import re
import sys
import xml.etree.ElementTree as ET

if len(sys.argv) != 2:
    raise SystemExit("Usage: harden_android.py <flutter-project-directory>")

project = Path(sys.argv[1]).resolve()
android = project / "android"
manifest = android / "app/src/main/AndroidManifest.xml"
xml_dir = android / "app/src/main/res/xml"
gradle = android / "app/build.gradle.kts"

if not manifest.is_file():
    raise SystemExit(f"ERROR: Android manifest not found: {manifest}")
if not gradle.is_file():
    raise SystemExit(f"ERROR: Kotlin Gradle file not found: {gradle}")

xml_dir.mkdir(parents=True, exist_ok=True)
(xml_dir / "network_security_config.xml").write_text(
    '''<?xml version="1.0" encoding="utf-8"?>
<network-security-config>
    <base-config cleartextTrafficPermitted="false">
        <trust-anchors>
            <certificates src="system" />
        </trust-anchors>
    </base-config>
</network-security-config>
''',
    encoding="utf-8",
)

(xml_dir / "data_extraction_rules.xml").write_text(
    '''<?xml version="1.0" encoding="utf-8"?>
<data-extraction-rules>
    <cloud-backup>
        <exclude domain="root" path="." />
        <exclude domain="file" path="." />
        <exclude domain="database" path="." />
        <exclude domain="sharedpref" path="." />
        <exclude domain="external" path="." />
    </cloud-backup>
    <device-transfer>
        <exclude domain="root" path="." />
        <exclude domain="file" path="." />
        <exclude domain="database" path="." />
        <exclude domain="sharedpref" path="." />
        <exclude domain="external" path="." />
    </device-transfer>
</data-extraction-rules>
''',
    encoding="utf-8",
)

ET.register_namespace("android", "http://schemas.android.com/apk/res/android")
manifest_tree = ET.parse(manifest)
root = manifest_tree.getroot()
android_ns = "{http://schemas.android.com/apk/res/android}"
app = root.find("application")
if app is None:
    raise SystemExit("ERROR: Android manifest has no application element")
app.set(android_ns + "usesCleartextTraffic", "false")
app.set(android_ns + "networkSecurityConfig", "@xml/network_security_config")
app.set(android_ns + "allowBackup", "false")
app.set(android_ns + "fullBackupContent", "false")
app.set(android_ns + "dataExtractionRules", "@xml/data_extraction_rules")
ET.indent(manifest_tree, space="    ")
manifest_tree.write(manifest, encoding="utf-8", xml_declaration=True)

source = gradle.read_text(encoding="utf-8")
if "isMinifyEnabled = true" not in source:
    source, count = re.subn(
        r"(?m)^(\s*)release\s*\{",
        lambda m: (
            m.group(1) + "release {\n"
            + m.group(1) + "    isMinifyEnabled = true\n"
            + m.group(1) + "    isShrinkResources = true\n"
            + m.group(1) + '    proguardFiles(getDefaultProguardFile("proguard-android-optimize.txt"), "proguard-rules.pro")'
        ),
        source,
        count=1,
    )
    if count != 1:
        raise SystemExit("ERROR: could not safely find the Android release build type to enable R8")

# Always configure release signing with the supplied production key. There is no debug fallback.
signing_block = '''    signingConfigs {
        create("release") {
            val releaseTaskRequested = gradle.startParameter.taskNames.any {
                it.contains("release", ignoreCase = true)
            }
            val releaseStore = System.getenv("ANDROID_KEYSTORE_PATH")
            val releaseStorePassword = System.getenv("ANDROID_KEYSTORE_PASSWORD")
            val releaseKeyAlias = System.getenv("ANDROID_KEY_ALIAS")
            val releaseKeyPassword = System.getenv("ANDROID_KEY_PASSWORD")
            val credentialsPresent = !releaseStore.isNullOrBlank() &&
                !releaseStorePassword.isNullOrBlank() &&
                !releaseKeyAlias.isNullOrBlank() &&
                !releaseKeyPassword.isNullOrBlank()
            if (releaseTaskRequested && !credentialsPresent) {
                throw GradleException("Production release signing secrets are required.")
            }
            if (credentialsPresent) {
                storeFile = file(releaseStore!!)
                storePassword = releaseStorePassword!!
                keyAlias = releaseKeyAlias!!
                keyPassword = releaseKeyPassword!!
            } else {
                // Permit unsigned debug builds for PR validation, but release tasks
                // fail closed above and can never silently use the debug key.
                storeFile = file("missing-release-keystore.jks")
                storePassword = "missing"
                keyAlias = "missing"
                keyPassword = "missing"
            }
        }
    }
'''
if 'create("release")' in source:
    source = re.sub(r'(?s)    signingConfigs\s*\{.*?\n    \}\n(?=\s*buildTypes\s*\{)', signing_block, source, count=1)
else:
    match = re.search(r"(?m)^\s*buildTypes\s*\{", source)
    if not match:
        raise SystemExit("ERROR: could not safely find Android buildTypes in Gradle file")
    source = source[:match.start()] + signing_block + "\n" + source[match.start():]

source, count = re.subn(
    r'(?m)^\s*signingConfig\s*=.*$',
    '            signingConfig = signingConfigs.getByName("release")',
    source,
    count=1,
)
if count != 1:
    raise SystemExit("ERROR: could not safely set release signing config")
if 'signingConfig = signingConfigs.getByName("debug")' in source:
    raise SystemExit("ERROR: debug signing fallback is forbidden")

gradle.write_text(source, encoding="utf-8")
proguard = android / "app/proguard-rules.pro"
if not proguard.exists():
    proguard.write_text(
        "# Keep Flutter embedding and plugin entry points safe under R8.\n"
        "-keep class io.flutter.embedding.** { *; }\n"
        "-keep class io.flutter.plugin.** { *; }\n"
        "# Flutter references Play Store deferred-component classes that are not used by this APK.\n"
        "-dontwarn com.google.android.play.core.**\n",
        encoding="utf-8",
    )

# Always ensure the Flutter deferred-component references don't break R8 when
# Play Core split-install support isn't bundled. This APK does not use deferred components.
proguard = android / "app/proguard-rules.pro"
rules = proguard.read_text(encoding="utf-8")
if "-dontwarn com.google.android.play.core.**" not in rules:
    proguard.write_text(
        rules.rstrip() + "\n# Flutter references Play Store deferred-component APIs not used by this app.\n"
        "-dontwarn com.google.android.play.core.**\n",
        encoding="utf-8",
    )

# Keep the Gradle wrapper compatible with the Android Gradle Plugin version generated by
# the current Flutter template. AGP in this project requires Gradle 8.13, while the
# generated wrapper may still be 8.12.
wrapper = android / "gradle/wrapper/gradle-wrapper.properties"
if not wrapper.is_file():
    raise SystemExit(f"ERROR: Gradle wrapper properties not found: {wrapper}")
wrapper_source = wrapper.read_text(encoding="utf-8")
wrapper_source, wrapper_count = re.subn(
    r"(?m)^distributionUrl=.*$",
    "distributionUrl=https\\://services.gradle.org/distributions/gradle-8.13-bin.zip",
    wrapper_source,
    count=1,
)
if wrapper_count != 1:
    raise SystemExit("ERROR: could not safely update Gradle wrapper distributionUrl")
wrapper.write_text(wrapper_source, encoding="utf-8")


print("Applied: HTTPS-only network policy, Android backup restrictions, R8 shrinking, and fail-closed production release signing.")
